import CoursePage from "@/components/CoursePage";
import { DEFAULT_COURSE } from "@/content/courses";

// Root URL renders the flagship (AINE) course. The LMS button targets
// /{slug}/ pages generated by app/[slug]/page.tsx, so hitting root directly
// is a sensible catch-all rather than a 404.
export default function Home() {
  return <CoursePage course={DEFAULT_COURSE} />;
}
